'use strict';

class Token {
  constructor(subject) {
    this.subject = subject;
    this.issuedBy = '@fx/token';
  }

  get value() {
    return this.subject;
  }

  toString() {
    return 'Token(' + this.subject + ')';
  }
}

function make(subject) {
  if (typeof subject !== 'string') throw new TypeError('subject must be a string');
  return new Token(subject);
}

module.exports = { Token: Token, make: make, VERSION: '2.0.0' };
